<?php require dirname(__DIR__).'/includes/bootstrap.php';$u=require_role(['ADMIN']);handle_form(function()use($u){$sr=post('showroom');must(db_one('SELECT 1 FROM showroom WHERE ma_showroom=?',[$sr]),'Showroom không tồn tại.');execute('INSERT INTO chi_tien(ma_showroom,so_khung_vin,loai,so_tien,ngay_chi,ma_chung_tu,nguoi_ghi_nhan_id,noi_dung)VALUES(?,?,?,?,?,?,?,?)',[$sr,post('vin')?:null,valid_text(post('loai'),30),vnd(post('amount')),valid_date(post('date')),valid_text(post('reference'),100),$u['id'],valid_text(post('content'),255)]);audit('GHI_CHI_TIEN','chi_tien',(string)insert_id());},'admin/chi_tien.php');page_start('Khoản chi thực tế');echo '<div class="panel">';token_form();select_field('showroom','Showroom',choices('SELECT * FROM showroom','ma_showroom','ten_showroom'),'MAIN',true);field('vin','VIN (nếu chi cho xe cụ thể)');select_field('loai','Loại chi',['MUA_XE'=>'Mua xe','VAN_HANH'=>'Vận hành','KHAC'=>'Khác'],'MUA_XE',true);field('amount','Số tiền','','number','required min="1"');field('date','Ngày chi',date('Y-m-d\TH:i'),'datetime-local','required');field('reference','Mã chứng từ','','text','required');field('content','Nội dung','','text','required');echo '<button>Ghi nhận chi</button></form></div>';table_start(['Ngày','Showroom','Nội dung','Số tiền']);foreach(db_all('SELECT * FROM chi_tien ORDER BY ngay_chi DESC LIMIT 150')as$r)echo '<tr><td>'.e($r['ngay_chi']).'</td><td>'.e($r['ma_showroom']).'</td><td>'.e($r['noi_dung']).'</td><td>'.e(money($r['so_tien'])).'</td></tr>';table_end();page_end();
